'use strict';
(()=>{const get=id=>document.getElementById(id),live=document.body.dataset.shaiLive==='true';let busy=false;
get('shai-mode').textContent=live?'LIVE AI · ANSWERS MAY BE IMPERFECT':'GUIDE MODE · PREWRITTEN ANSWERS';
function message(role,text,source,href){const bubble=document.createElement('article');bubble.className='shai-message '+role;const label=document.createElement('strong');label.textContent=role==='user'?'YOU':'ShAI';const p=document.createElement('p');p.textContent=text;bubble.append(label,p);if(source){const small=document.createElement('small');small.textContent='Source: '+source;bubble.append(small);}if(href&&['#home','#contact','#operations','#workflow','#approach'].includes(href)){const a=document.createElement('a');a.href=href;a.textContent='Explore this →';bubble.append(a);}get('shai-messages').append(bubble);while(get('shai-messages').children.length>16)get('shai-messages').firstElementChild.remove();}
async function ask(text){if(busy)return;const q=text.trim();if(!q||q.length>600){get('shai-status').textContent='Ask a question between 1 and 600 characters.';return;}busy=true;get('shai-send').disabled=true;message('user',q);get('shai-question').value='';get('shai-status').textContent=live?'ShAI is composing an answer…':'Finding a portfolio topic…';try{let r;if(live){const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q}),signal:AbortSignal.timeout(25000)});if(!response.ok)throw Error('Live chat is unavailable or its limit was reached. Please try later.');r=await response.json();if(typeof r.answer!=='string'||r.answer.length>5000)throw Error('The server returned an invalid answer.');}else r=ShAIKnowledge.answer(q);message('assistant',r.answer,r.source,r.href);get('shai-status').textContent=live?'Each answer is independent; no conversation history is sent.':'Prewritten topic match. No AI model or network request used.';}catch(e){get('shai-status').textContent=e.name==='TimeoutError'?'ShAI took too long. Try again later.':e.message;}finally{busy=false;get('shai-send').disabled=false;}}
get('shai-form').onsubmit=e=>{e.preventDefault();ask(get('shai-question').value);};document.querySelectorAll('[data-shai-question]').forEach(b=>b.onclick=()=>ask(b.dataset.shaiQuestion));get('shai-clear').onclick=()=>{if(busy)return;get('shai-messages').replaceChildren();get('shai-status').textContent='Conversation cleared from this page.';};message('assistant',"Hey, I’m ShAI—current Shai, digital edition. I’m her portfolio representative, not Shai herself. I can walk you through the projects, explain the decisions, and admit when something isn’t built yet. Ask me a question.",'Owner-provided background and documented projects','#home');
})();
